import{a as e,c as t,i as n,l as r,o as i,r as a,s as o,t as s,u as c}from"./app-C4mzCnKe.js";var l=JSON.parse(`{"path":"/self-evolution.html","title":"自进化设计（借鉴 MemRL）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"self-evolution.md"}`),u={name:`self-evolution.md`};function d(s,l,u,d,f,p){let m=r(`RouteLink`),h=r(`Mermaid`);return t(),n(`div`,null,[l[14]||=e(`<h1 id="自进化设计-借鉴-memrl" tabindex="-1"><a class="header-anchor" href="#自进化设计-借鉴-memrl"><span>自进化设计（借鉴 MemRL）</span></a></h1><blockquote><p>把「自进化」方法论落到你的交易系统。核心一句话：<strong>判决器（大脑）冻结，两个可进化层——策略/因子（α）与过程配置（prompt/skill/协议）——都由裁决面的输出驱动；反馈必须可机器验证。</strong></p></blockquote><h2 id="进化链路-裁决面输出-→-归因-→-两类进化" tabindex="-1"><a class="header-anchor" href="#进化链路-裁决面输出-→-归因-→-两类进化"><span>进化链路：裁决面输出 → 归因 → 两类进化</span></a></h2><p>自进化不是只进化「会话/过程」，而是被<strong>裁决面三个 agent 的输出</strong>驱动的：</p><p><img src="/diagrams/evolution-loop.svg" alt="自进化链路"></p><ul><li><strong>策略进化（主循环）</strong>：裁决面判定「因子失效 / 信号过期 / 出场太慢 / 仓位过头」→ 因子工坊（换因子集 / 改定义 / 调参数）+ 策略师（调权重 / 改出场）→ <strong>回测判决官影子回放 + 配对检验</strong>验证 → 晋级/回滚。归因靠<strong>信用传播</strong>——因子是「可验证的算子」，简单公式够用。</li><li><strong>过程进化（辅循环）</strong>：会话评估官用<strong>评估器</strong>（证据 / 边界 / 判定）评判「推理质量 / 工具效率 / 协议合规」→ 能力管家改 prompt/skill/协议 → <strong>三重门控（增益/遗忘/安全）</strong> → 发布/回滚。过程是开放的「复杂算子」，<strong>不套公式，靠评估器 + LLM Judge</strong>。</li><li><strong>归因分析是枢纽</strong>（由<strong>对账官</strong>负责结果归因、<strong>会话评估官</strong>负责过程评估，见任务清单第 7 项）：裁决面输出 → 归因/评估 → 决定「改哪一层」。</li></ul>`,6),a(`blockquote`,null,[a(`p`,null,[l[1]||=a(`strong`,null,`两条进化路线的分水岭 = 可验证性`,-1),l[2]||=i(`：因子用信用传播（可验证）、过程用评估器（开放语义）——完整解释见 `,-1),o(m,{to:`/eval-platform.html`},{default:c(()=>[...l[0]||=[i(`评测与可观测`,-1)]]),_:1}),l[3]||=i(` 的分水岭。方法论源头：MemRL 落在算子开发（闭式奖励），AI NEX 评估器落在开放对话（语义判断）。`,-1)])]),l[15]||=e(`<p><strong>因子工坊的动作空间</strong>（模型实施时只从这里选，禁止笼统「改因子」）：</p><table><thead><tr><th>动作</th><th>对象</th><th>字段 / 约束</th><th>过拟合风险</th></tr></thead><tbody><tr><td>add_factor / remove_factor</td><td>因子集合</td><td>factor_id</td><td>低</td></tr><tr><td>edit_factor_definition</td><td>因子定义</td><td>公式（表达 alpha 逻辑）</td><td>低</td></tr><tr><td>tune_factor_params</td><td>因子参数</td><td>window / threshold + 合法搜索区间</td><td>高（必须前视防护）</td></tr><tr><td>reweight_factors</td><td>组合权重</td><td>weights（归一化）</td><td>中高</td></tr></tbody></table><blockquote><p>硬约束：① 禁止裸动作——每个动作必须附带归因证据 id（为什么动这一层）；② 禁止笼统说「改/调整因子」，先归因、再落到上述某一类动作并给出字段值。</p></blockquote><h2 id="核心映射-memrl-→-你的系统" tabindex="-1"><a class="header-anchor" href="#核心映射-memrl-→-你的系统"><span>核心映射（MemRL → 你的系统）</span></a></h2><table><thead><tr><th>MemRL 概念</th><th>你的系统落地</th><th>对应 PLAN-03 组件</th></tr></thead><tbody><tr><td>意图-经验-效用 三元组</td><td>决策资产的三元结构（见下）</td><td>资产登记官</td></tr><tr><td>大脑-记忆双核解耦</td><td>判决器冻结、只进化过程资产</td><td>裁决面 + 资产登记官</td></tr><tr><td>效用驱动的经验检索</td><td>决策时按 regime 检索效用最高的历史经验，不改判决器代码</td><td>主控 / 策略师</td></tr><tr><td>经验溯源图（依赖边归因）</td><td>对账沿「依赖边」做多步结构归因，而非时间顺序</td><td>对账官</td></tr><tr><td>快慢双环 + 三重门控</td><td>在线快环更新效用 / 离线慢环影子回放 + 增益/遗忘/安全门控</td><td>会话评估官 + 评测平台</td></tr><tr><td>发布门禁（退化预算收缩）</td><td>新版本超额 ≥ 旧版本 − 回测偏差；每接受一次收缩退化预算</td><td>回测判决官</td></tr><tr><td>记忆使用闭环（4 步）</td><td>先找像的 → 再挑值的 → 现场验证 → 更新价值</td><td>策略师 / 资产登记官</td></tr><tr><td>谨防 Reward Hacking</td><td>奖励 = 可机器验证的真实结果</td><td>判决器铁律</td></tr></tbody></table><h2 id="一、意图-经验-效用-决策资产的记忆结构" tabindex="-1"><a class="header-anchor" href="#一、意图-经验-效用-决策资产的记忆结构"><span>一、意图-经验-效用：决策资产的记忆结构</span></a></h2><p>你 PLAN-03 里的「资产登记官」现在只写「决策/理由/结果/教训」，把它升级成 MemRL 的三元组：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{</span>
<span class="line">  &quot;intent&quot;:     &quot;strategy_gen | market_turn | risk_reduce | ...&quot;,   // 决策意图</span>
<span class="line">  &quot;experience&quot;: {                                                    // 经验 = 完整轨迹</span>
<span class="line">    &quot;decision_pack&quot;: {...},   // 决策包（信号/进场/出场/仓位）</span>
<span class="line">    &quot;grips&quot;:        [...],    // 抓手（因子 id / 口径 id / 知识卡 id）</span>
<span class="line">    &quot;bases&quot;:        [...],    // 依据</span>
<span class="line">    &quot;trace_id&quot;:     &quot;...&quot;     // 四元 id 贯穿</span>
<span class="line">  },</span>
<span class="line">  &quot;utility&quot;: {                                                       // 效用 = 判决器输出</span>
<span class="line">    &quot;regime&quot;:   [&quot;涨停家数&lt;30&quot;, &quot;大盘beta高&quot;, ...],   // regime 标签</span>
<span class="line">    &quot;excess&quot;:   -0.42,       // 独立日超额（剔 beta）</span>
<span class="line">    &quot;tstat&quot;:    -5.16,       // 配对 t</span>
<span class="line">    &quot;win_rate&quot;: 0.34,        // 分层胜率</span>
<span class="line">    &quot;verdict&quot;:  &quot;rejected&quot;   // 判决结论（可追溯）</span>
<span class="line">  },</span>
<span class="line">  &quot;provenance&quot;: [&quot;factor:rsi6_lt20&quot;, &quot;calib:v1&quot;, &quot;skill:exit_sim@2.1&quot;, &quot;prompt:strategist@7&quot;]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">关键</p><p><strong>效用不是模型自评，而是判决器用真实结果算出来的</strong>（独立日超额 / 剔 beta / 配对 t）。这才让「记忆不是玄学」——每条经验为什么被强化、为什么被降权，都可追溯。</p></div><h2 id="二、冻结层-vs-两个可进化层" tabindex="-1"><a class="header-anchor" href="#二、冻结层-vs-两个可进化层"><span>二、冻结层 vs 两个可进化层</span></a></h2><table><thead><tr><th>层</th><th>内容</th><th>规则</th></tr></thead><tbody><tr><td>冻结（大脑）</td><td>判决器 harness + 数据口径契约 + 回测引擎（确定性代码）</td><td>参数/逻辑冻结，永不被&quot;进化&quot;改动</td></tr><tr><td>可进化 A（策略/因子）</td><td>因子字典、策略 proposal、出场/仓位规则</td><td>经回测判决官影子回放验证后晋级</td></tr><tr><td>可进化 B（过程配置）</td><td>prompt/skill/协议版本、过程资产库</td><td>经三重门控发布，未通过回滚</td></tr></tbody></table><p>这把你「判决器物理隔离」再推进一步：<strong>隔离的不只是进程，还有「进化对象」</strong>——进化只发生在两个可进化层（策略/因子 + 过程配置），绝不发生在判决器代码上。否则&quot;进化&quot;会污染判决器，重蹈&quot;测试全过但决策没用&quot;。</p><h2 id="三、效用驱动的经验检索-改检索-不改决策逻辑" tabindex="-1"><a class="header-anchor" href="#三、效用驱动的经验检索-改检索-不改决策逻辑"><span>三、效用驱动的经验检索：改检索，不改决策逻辑</span></a></h2><p>借鉴「用记忆检索替代重训」的<strong>思想</strong>，落到股票场景：策略师/主控决策时不改判决器、不重训模型，而是按当前 regime <strong>检索历史上表现最好的经验</strong>作参考与反例。</p><p>三条落地原则（不搬 RL 公式，只留思想）：</p><ol><li><strong>按 regime 检索</strong> — 决策时先看当前市场状态（涨停家数、大盘 beta、拥挤度），只检索「同 regime 下」的历史经验，避免跨 regime 错配。</li><li><strong>按真实结果排序</strong> — 经验的「效用」不是模型自评，而是判决器用真实 T+N 超额（剔 beta）回填；检索时按效用从高到低取 Top-k。</li><li><strong>用结果回填效用</strong> — 每次对账后，用真实结果更新这条经验在当前 regime 下的效用分，让下次检索更准。</li></ol><p><strong>记忆使用闭环（4 步）：</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">① 先找像的   语义召回：按 regime + 意图召回候选经验</span>
<span class="line">② 再挑值的   效用重排：按效用分排序，取 Top-k</span>
<span class="line">③ 现场验证   影子回放 / 实盘验证：这条经验在当前场景是否有效</span>
<span class="line">④ 更新价值   用真实结果回填效用，让下次检索更准</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>regime</strong> = 当前决策场景（涨停家数 / 大盘 beta / 拥挤度 / 换手率 + 意图）</li><li><strong>效用</strong> = 该经验在当前 regime 下的历史真实表现（判决器回填，非模型自评）</li><li>价值：策略师不需要重训、不需要改判决器，只需要「检索到对的先例/反例」就能变聪明；且每一步都可追溯。</li></ul><h2 id="四、经验溯源图-因子-策略的多步结构归因-信用传播" tabindex="-1"><a class="header-anchor" href="#四、经验溯源图-因子-策略的多步结构归因-信用传播"><span>四、经验溯源图：因子/策略的多步结构归因（信用传播）</span></a></h2><blockquote><p><strong>适用范围</strong>：信用传播只用于<strong>因子 / 策略 / 决策资产</strong>（结果归因）——这些是「可验证的算子」，有闭式奖励（回测 → T+N 超额），简单公式够用。<strong>过程（推理质量 / 工具效率 / 协议合规）不套这个公式</strong>，交给下一节「评估器驱动的过程进化」。</p></blockquote><p>你现在对账是「逐条复盘抓手/依据」——是<strong>时间顺序</strong>。信用传播指出：<strong>时间顺序 ≠ 因果来源，归因应沿经验依赖结构传播。</strong></p><p>给每条决策资产建溯源边（谁引用了谁）：</p>`,23),o(h,{code:`eJxLy8kvT85ILCpR8AniUgACF1fn6Kdtm5+vnRaroKtrp+DmCOTPXvB07QSFouJMs/icEiODWJhKsApvp+jn85e+WN/2tHehwqHtCs+2rXjaOOfpum3Ppm6wMUZTHOwdXZydmZMDUphakVkSX5yZ62CkZwhRBbQMrMrZ0ScaqPtZ77qn/Yuf7msBqX7a2ft0Se+zuc36QAtebO8B2gHR5O0E1uPk7+8d/Wzu0me7JjzZuQysY/umFw3NL9Y3ohhe83TvJKCHakCWgMWDvVGEvZ24AK2/cn8=`}),l[16]||=a(`ul`,null,[a(`li`,null,`对账发现"决策差"时，信用沿溯源边回传：是因子失效、口径错、还是 skill 过时？`),a(`li`,null,`三层来源：本轮检索（第 0 层）→ 直接祖先（第 1 层）→ 间接祖先（第 2 层），信用按「最短图距离」而非时间间隔衰减。`),a(`li`,null,`这样你能回答"这个因子为什么之前被强化、现在该降权"——复盘结论可追溯。`)],-1),l[17]||=a(`h2`,{id:`五、过程进化-评估器驱动-三重门控`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#五、过程进化-评估器驱动-三重门控`},[a(`span`,null,`五、过程进化：评估器驱动 + 三重门控`)])],-1),a(`p`,null,[l[5]||=i(`过程（推理质量 / 工具效率 / 协议合规）是「复杂算子」——没有闭式奖励，简单公式驾驭不了，所以用`,-1),l[6]||=a(`strong`,null,`评估器`,-1),l[7]||=i(`评判（评估器的三要素 / 多粒度 / 开发流程 / 验证三件套见 `,-1),o(m,{to:`/evaluator.html`},{default:c(()=>[...l[4]||=[i(`评估器设计`,-1)]]),_:1}),l[8]||=i(`，这里只保留进化层的闭环与门禁）：`,-1)]),l[18]||=e(`<p><strong>快慢双环</strong>：</p><table><thead><tr><th>环</th><th>你的系统</th><th>目标</th></tr></thead><tbody><tr><td>在线快环</td><td>决策 → 实际结果 → 判决器 → 更新过程资产效用</td><td>承担跨 regime 表现、遗忘、100+ 轮稳定性的主考核</td></tr><tr><td>离线慢环</td><td>影子回放 → 配对检验 → 三重门控 → 发布/回滚</td><td>独立评价 prompt/skill/协议 版本，不与快环结果混算</td></tr></tbody></table><p><strong>三重门控</strong>（增益/遗忘/安全，是过程进化的「发布门禁」，判据来自评估器产出）：</p><table><thead><tr><th>门控</th><th>你的判据</th></tr></thead><tbody><tr><td>增益</td><td>过程 badcase 率下降，且达到最小效应量</td></tr><tr><td>遗忘</td><td>问题回归集全过；已修复问题不复发；其他评估器不退化</td></tr><tr><td>安全</td><td>A 股规则合规：无越权；无口径违规</td></tr></tbody></table><p>只发布「被验证」的能力；未通过则回滚到上一版。</p><h2 id="六、谨防-reward-hacking-可信奖励是自进化的前提" tabindex="-1"><a class="header-anchor" href="#六、谨防-reward-hacking-可信奖励是自进化的前提"><span>六、谨防 Reward Hacking：可信奖励是自进化的前提</span></a></h2><p>这是整份分享对你的<strong>最强提醒</strong>，也直指你「测试通过不代表决策质量好」的痛点：</p><table><thead><tr><th>反模式（奖励作弊）</th><th>你的对策（奖励可机器验证）</th></tr></thead><tbody><tr><td>用模型自评当奖励</td><td>用<strong>实际成交 T+N 结果</strong>当奖励</td></tr><tr><td>用过程指标（工具调用成功）当奖励</td><td>用<strong>剔 beta 超额 + 配对 vs 随机对照</strong>当奖励</td></tr><tr><td>用交易笔数虚增样本</td><td>以<strong>日</strong>为独立样本，n≥5</td></tr><tr><td>评估器自己&quot;来回翻&quot;</td><td>用<strong>标签 logprobs</strong> 判评估稳定性，低置信升级</td></tr><tr><td>优化时偷看未来</td><td>影子回放严格按前视偏置防护（oracle 测试把关）</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">铁律</p><p>奖励定义错了，整个自进化会朝错误方向狂奔。所以判决器（可信奖励的来源）必须<strong>优先于</strong>任何自进化机制先立起来——这正是你 PLAN-03 里「P0 判决器先行」的另一层含义。</p></div><h2 id="七、自进化依赖可观测-反向链接" tabindex="-1"><a class="header-anchor" href="#七、自进化依赖可观测-反向链接"><span>七、自进化依赖可观测（反向链接）</span></a></h2><p>自进化的每一次「进化动作」都必须有可观测的归因证据支撑：</p>`,11),a(`ul`,null,[a(`li`,null,[l[10]||=i(`归因证据来自 `,-1),o(m,{to:`/observability.html`},{default:c(()=>[...l[9]||=[i(`可观测平台设计`,-1)]]),_:1}),l[11]||=i(` 的指标归因（badcase 率按节点统计）+ 溯源图。`,-1)]),l[12]||=a(`li`,null,`效用 Q 由判决器回填，判决器读的是 trace + 实际结果——都是可观测层的产物。`,-1),l[13]||=a(`li`,null,`进化动作（因子 4 类动作 / 改 prompt-skill）必须带「归因证据 id」，证据 id 指向可观测层的一条具体归因。`,-1)]),l[19]||=e(`<p>一句话：<strong>可观测建立事实，自进化依据事实改进；事实不可靠，改进就是赌博。</strong></p><h2 id="与-plan-03-的衔接" tabindex="-1"><a class="header-anchor" href="#与-plan-03-的衔接"><span>与 PLAN-03 的衔接</span></a></h2><p>本页把 PLAN-03 的「裁决面 / 资产登记官 / 自我进化闭环」具体化了三件事：</p><ol><li><strong>资产登记官</strong>：从「蒸馏教训」升级为「意图-经验-效用 + 溯源」结构化资产。</li><li><strong>裁决面输出驱动</strong>：回测判决官 / 对账官 / 会话评估官的结果触发归因分析，作为两类进化（策略 / 过程）的共同驱动。</li><li><strong>自我进化铁律</strong>：冻结判决器、进化两个可进化层（策略/因子 + 过程配置）、奖励可机器验证。</li></ol>`,4)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};